import { fireEvent, render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import type { FairReport } from "../../api/types";
import { formatProbability, formatUsd } from "../../lib/format";
// A real report generated by the backend (fair.agent.fallback_report on the
// healthcare example), so these types are checked against the real shape
import fixture from "../../test/fairReport.json";
import FinancialExposure from "./FinancialExposure";

const report = fixture as unknown as FairReport;

function copy(overrides: Partial<FairReport> = {}): FairReport {
  return { ...structuredClone(report), ...overrides };
}

test("headline tiles show the combined figures exactly as the backend formats them", () => {
  render(<FinancialExposure fair={report} />);
  const tiles = screen.getAllByRole("definition");
  expect(tiles.map((t) => t.textContent)).toEqual([
    formatUsd(report.combined.ale_mean),
    formatProbability(report.combined.prob_any_loss),
    formatUsd(report.combined.p99),
    formatProbability(report.combined.prob_exceeds_tolerance),
  ]);
  expect(screen.getByText(/derived from risk appetite/)).toBeInTheDocument();
});

test("escalation, its reasons and contract conditions are shown", () => {
  render(
    <FinancialExposure
      fair={report}
      decision={{
        escalated_by_fair: true,
        base_recommendation: "APPROVE",
        fair_reasons: ["expected annual loss $605K reaches the derived tolerance of $200K"],
        conditions: ["Share fewer records with the vendor: expected annual loss falls to $302K [run_03]"],
      }}
    />,
  );
  expect(screen.getByText(/Raised from APPROVE by financial exposure/)).toBeInTheDocument();
  expect(screen.getByText(/reaches the derived tolerance/)).toBeInTheDocument();
  expect(screen.getByText("Acceptable if:")).toBeInTheDocument();
  expect(screen.getByText(/falls to \$302K/)).toBeInTheDocument();
});

test("a partial or assumption-heavy report says it did not change the decision", () => {
  render(<FinancialExposure fair={copy({ status: "partial" })} />);
  expect(screen.getByText(/did not change the recommendation/)).toBeInTheDocument();
});

test("a skipped run explains why, and no FAIR data renders nothing", () => {
  const { container, rerender } = render(<FinancialExposure fair={null} />);
  expect(container).toBeEmptyDOMElement();
  rerender(<FinancialExposure fair={{ skipped: "OFAC sanctions match already rejects the vendor" }} />);
  expect(screen.getByText(/Not quantified: OFAC sanctions match/)).toBeInTheDocument();
});

test("scenario tabs switch the drivers chart", async () => {
  const user = userEvent.setup();
  render(<FinancialExposure fair={report} />);
  const drivers = () => within(screen.getByRole("list", { name: "Inputs ranked by influence" }));
  expect(drivers().getByText("Response cost")).toBeInTheDocument();
  await user.click(screen.getByRole("tab", { name: /Insolvency/ }));
  expect(drivers().getByText("Replacement cost")).toBeInTheDocument();
  expect(drivers().queryByText("Response cost")).not.toBeInTheDocument();
});

test("the loss curve can be read from the keyboard", () => {
  render(<FinancialExposure fair={report} />);
  const chart = screen.getByRole("img", { name: /Chance per year that losses reach/ });
  chart.focus();
  fireEvent.keyDown(chart, { key: "ArrowRight" });
  // The tolerance ($200K) is below the smallest simulated loss, so the curve
  // starts with a flat stretch at the chance of any loss, from tolerance / 1.5
  const smallest = report.combined.loss_exceedance_curve.find((p) => p.loss > 0)!;
  expect(report.tolerance!.value_usd).toBeLessThan(smallest.loss);
  expect(screen.getByRole("status")).toHaveTextContent(`${formatProbability(smallest.probability)} per year`);
  expect(screen.getByRole("status")).toHaveTextContent(
    `losses of at least ${formatUsd(report.tolerance!.value_usd / 1.5)}`,
  );
  expect(screen.getByText(`Tolerance ${formatUsd(report.tolerance!.value_usd)}`)).toBeInTheDocument();
  fireEvent.blur(chart);
  expect(screen.queryByRole("status")).not.toBeInTheDocument();
});

test("each driver bar explains itself on focus, and every chart has a table view", () => {
  render(<FinancialExposure fair={report} />);
  const top = report.scenarios[0]!.drivers[0]!;
  const bar = screen.getByLabelText(new RegExp(`^Response cost: expected loss ${formatUsd(top.low_ale).replace("$", "\\$")}`));
  fireEvent.focus(bar);
  expect(screen.getByRole("status")).toHaveTextContent(`${formatUsd(top.low_ale)} – ${formatUsd(top.high_ale)}`);
  expect(screen.getAllByText("Show as table")).toHaveLength(2);
});

test("controls, the facts that would sharpen the estimate, and the investigation", () => {
  render(<FinancialExposure fair={report} />);
  const table = screen.getByRole("table", { name: "What contract terms would change" });
  expect(within(table).getAllByRole("row")).toHaveLength(report.controls.length + 1);
  expect(within(table).getByText("Recommended")).toBeInTheDocument();
  expect(screen.getByText(/Control effects are planning assumptions/)).toBeInTheDocument();
  expect(screen.getByText(/To sharpen this estimate, tell us/).closest("p")).toHaveTextContent(
    "your dollar risk tolerance",
  );
  expect(screen.getByText(/How the agent investigated \(5 steps\)/)).toBeInTheDocument();
  expect(screen.getByText(/17,053 tokens/)).toBeInTheDocument();
});
